def f(g):
    H,W=len(g),len(g[0]); bg=max(set(x for r in g for x in r), key=lambda c: sum(r.count(c) for r in g))
    # shape color: the minority non-bg color
    cnt={c:sum(r.count(c) for r in g) for c in set(x for r in g for x in r) if c!=bg}
    sc=max(cnt,key=cnt.get) if cnt else None
    seen=set(); out=[r[:] for r in g]; chg=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==sc and (i,j) not in seen:
                st=[(i,j)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); comp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and g[x][y]==sc and (x,y) not in seen: st.append((x,y))
                mx=max(b for a,b in comp)
                if mx<W-1:
                    D=W-1-mx
                    for a,b in comp:
                        x,y=a+b-D if False else (a,b+D)
                        x_,y_=a,b+D
                        if y_<W and g[a][b+D]==bg:
                            out[a][b+D]=1; chg.append((a,b+D))
    return out,chg

