import json
def f(T):
    out=[r[:] for r in T]
    obj_rows=[i for i,r in enumerate(T) if any(c==8 for c in r)]
    # split into objects: contiguous groups of rows
    objs=[]; cur=[obj_rows[0]]
    for i in obj_rows[1:]:
        if i==cur[-1]+1: cur.append(i)
        else: objs.append(cur); cur=[i]
    objs.append(cur)
    def runs(r):
        res=[]; j=0
        while j<len(r):
            if r[j]==8:
                s=j
                while j<len(r) and r[j]==8: j+=1
                res.append((s,j-s))
            else: j+=1
        return res
    for ob in objs:
        rs=[runs(T[i]) for i in ob]
        # align across objects: for each (start,dur) in object k, find matching start in another object with longer dur
        allrs={}
        for oi,(rr_,i_) in enumerate(zip(rs,obj)): allrs.setdefault(i_,{})
        for oi,(rr_,i_) in enumerate(zip(rs,obj)): pass
        for oi in range(len(objs)):
            for si in obj[objs[oi]]:
                for st,dur in runs(T[si]):
                    # find longer with same start in any other object
                    best=None
                    for k2 in range(len(objs)):
                        if k2==oi: continue
                        for s2,d2 in [x for rr2 in runs(T[s2]) for x in rr2 if rr2[0]!=s2 or True]:
                            pass
                    # simpler: scan all rows
                    for i2 in range(len(T)):
                        if i2 in objs[oi]: continue
                        for s2,d2 in runs(T[i2]):
                            if s2==st and d2>dur and (best is None or d2>best[1]): best=(s2,d2)
                    if best:
                        for j in range(si+best[1], len(T[si])):
                            out[si][j]=1
    return out
